import Select from "@marko-ui/shadcn/ui/select/select.marko";

static const fruits = [
  { value: "apple", label: "Apple" },
  { value: "banana", label: "Banana" },
  { value: "blueberry", label: "Blueberry" },
  { value: "grapes", label: "Grapes" },
  { value: "pineapple", label: "Pineapple" },
];

<Select items=fruits placeholder="Select a fruit"/>

import Select from "@marko-ui/shadcn/ui/select/select.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldContent from "@marko-ui/shadcn/ui/field/field-content.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import FieldGroup from "@marko-ui/shadcn/ui/field/field-group.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import Switch from "@marko-ui/shadcn/ui/switch/switch.marko";

static const fruits = [
  { value: "apple", label: "Apple" },
  { value: "banana", label: "Banana" },
  { value: "blueberry", label: "Blueberry" },
  { value: "grapes", label: "Grapes" },
  { value: "pineapple", label: "Pineapple" },
];

<let/alignItemWithTrigger=true>

<FieldGroup class="w-full max-w-xs">
  <Field orientation="horizontal">
    <FieldContent>
      <FieldLabel for="select-align-item-switch">Align Item</FieldLabel>
      <FieldDescription>Toggle to align the item with the trigger.</FieldDescription>
    </FieldContent>
    <Switch id="select-align-item-switch" ids={ hiddenInput: "select-align-item-switch" } checked:=alignItemWithTrigger/>
  </Field>
  <Field>
    <Select
      items=fruits
      defaultValue=["banana"]
      positioning={ placement: alignItemWithTrigger ? "bottom-start" : "bottom" }
    />
  </Field>
</FieldGroup>

